template.solver:
def solve(k):
    lo = 10 ** (k - 1)
    hi = 10 ** k
    for n in range(lo, hi):
        s = str(n)
        if '0' in s or len(set(s)) != k:
            continue
        ok = True
        for c in s:
            if n % int(c) != 0:
                ok = False
                break
        if ok:
            return sum(int(c) for c in s)
    return 0
